import React, { useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { RootState } from '../../store/store'
import {
  removerDoCarrinho,
  limparCarrinho
} from '../../store/Slice/carrinhoSlice'
import {
  CarrinhoContainer,
  CarrinhoHeader,
  CarrinhoLista,
  CarrinhoItem,
  CarrinhoTotal,
  CarrinhoButton
} from './styles'

const Carrinho = () => {
  const dispatch = useDispatch()
  const itens = useSelector((state: RootState) => state.carrinho.itens)

  const [isOpen, setIsOpen] = useState(true) // Controlando o estado de abertura do carrinho

  const calcularTotal = () => {
    return itens.reduce((total, item) => total + item.preco, 0).toFixed(2)
  }

  return (
    <CarrinhoContainer isOpen={isOpen}>
      {' '}
      {/* Passa a propriedade isOpen para o styled-component */}
      <CarrinhoHeader>
        <h3>Carrinho</h3>
        <button onClick={() => dispatch(limparCarrinho())}>Limpar</button>
      </CarrinhoHeader>
      <CarrinhoLista>
        {itens.map((item) => (
          <CarrinhoItem key={item.id}>
            <img src={item.image} alt={item.title} />
            <div>
              <h4>{item.title}</h4>
              <p>R$ {item.preco.toFixed(2)}</p>
              <button onClick={() => dispatch(removerDoCarrinho(item.id))}>
                Remover
              </button>
            </div>
          </CarrinhoItem>
        ))}
      </CarrinhoLista>
      <CarrinhoTotal>
        <p>Total: R$ {calcularTotal()}</p>
      </CarrinhoTotal>
      <CarrinhoButton>Continuar para a entrega</CarrinhoButton>
    </CarrinhoContainer>
  )
}

export default Carrinho
